import glob, re, datetime, collections
sev_re = re.compile(r'\[(ERROR|WARNING|INFO|DEBUG)\]')
per = collections.defaultdict(lambda: {"ERROR":0,"WARNING":0,"INFO":0})
for f in sorted(glob.glob('/app/logs/*.log')):
    date = f.split('/')[-1][:10]
    for line in open(f, errors='replace'):
        m = sev_re.search(line)
        if m and m.group(1) in ("ERROR","WARNING","INFO"):
            per[date][m.group(1)] += 1

today = "2025-08-12"
def rng(days_ago):
    return [(datetime.date.fromisoformat(today)-datetime.timedelta(days=k)).isoformat() for k in range(days_ago+1)]

def total(dates):
    return {s: sum(per.get(d,{}).get(s,0) for d in dates) for s in ("ERROR","WARNING","INFO")}

